Për produktet e prodhimit:
•	Kushtet e Garancisë
Të gjitha produktet që Univers Reklama ofron janë të garantuara për mungesë apo shfaqje defektesh për një periudhë kohore deri në 1 (një) vit, nga data e dorëzimit dhe faturimit.

Garancia e produktit përfshin realizimin dhe prodhimin e produktit sipas kërkesave, mirë-funksionimin e tij sipas parametrave teknik, dhe cilësinë e montimit të tij (në rastet kur aplikohet) për një periudhë prej 1 (një) viti.
Garancia nuk përfshin:
-	Zëvendësimi apo riparimin e pjesëve të produktit nga një tjetër Sipërmarrës/Furnitor;
-	Keqpërdorimi apo shpërdorimi i produktit;
-	Dëmtime nga akte të qëllimshme;
-	Mungesa e mirëmbajtjes;
-	Ndërhyrja nga persona të paautorizuar;

•	Kushtet e Garancisë
Të gjitha produktet që Univers Reklama ofron janë të garantuara për mungesë apo shfaqje defektesh për një periudhë kohore deri në 1 (një) vit, nga data e dorëzimit dhe faturimit.

Për produktet “Printime”, garancia e produktit përfshin:
-	Cilësia dhe ruajtja e ngjyrave të printimit
o	2 (dy) vjet për Outdoor;
o	3 (tre) vjet për Indoor;
-	Aplikimi
o	Ngjitja dhe montimi i produktit – 1 (një) vit.
Garancia nuk mbulon dëmtime të cilat shkaktohen nga:
-	Keqpërdorimi apo dëmtime të qëllimshme;
-	Mosaplikimi në mënyrën dhe kushtet e duhura teknike;
-	Mungesa e mirëmbajtjes së produktit;

using System.Collections.Generic;

        double totalZbritje;
        double totalPaTvsh;
        double cmimiMeTvsh;
        double cmimPaTvsh;
        double totalimetvsh = 0;
List<object[]> artikujt = new List<object[]>();
private void xrLabel19_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 totalZbritje = totalPaTvsh - Convert.ToDouble(GetCurrentColumnValue("TOTALIMETVSHMEZBRITJE")) + Convert.ToDouble(GetCurrentColumnValue("TVSHTOTAL"));
            xrLabel19.Text = totalZbritje.ToString("################################0.00");
}

private void xrTableCell16_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 int brutoNetoNivelCmimi = Convert.ToInt32(GetCurrentColumnValue("BRUTONETONIVELCMIMI"));
            if (brutoNetoNivelCmimi == 1)
            {
                cmimiMeTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI"));

                if (GetCurrentColumnValue("tvsh").ToString() != "")
                    cmimPaTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI")) * (1 - Math.Round(Convert.ToDouble(GetCurrentColumnValue("tvsh")), 2));
                else
                    cmimPaTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI"));

            }
            else
            {
                cmimPaTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI"));

                if (GetCurrentColumnValue("tvsh").ToString() != "")
                    cmimiMeTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI")) * (1 + Math.Round(Convert.ToDouble(GetCurrentColumnValue("tvsh")), 2));
                else cmimiMeTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI"));

            }
            totalPaTvsh += Convert.ToDouble(GetCurrentColumnValue("VLEFTAPATVSH"));
        }
private void xrTableCell1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 if (GetCurrentColumnValue("KODI") != null && GetCurrentColumnValue("KODI").ToString() != "")
            {
                if (GetCurrentColumnValue("AfatGarancie") != null && GetCurrentColumnValue("AfatGarancie").ToString() != "" && decimal.Parse(GetCurrentColumnValue("AfatGarancie").ToString()) != 0 && GetCurrentColumnValue("LlojGarancie") != null && GetCurrentColumnValue("LlojGarancie").ToString() != "")
                {
                    object[] obj = new object[4];
                    obj[0] = GetCurrentColumnValue("KODI");
                    obj[1] = GetCurrentColumnValue("PERSHKRIMI");
                    obj[2] = GetCurrentColumnValue("AfatGarancie");
                    obj[3] = GetCurrentColumnValue("LlojGarancie");
                    artikujt.Add(obj);
                }
            }
}

private void xrLabel1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 string autorizime = GetCurrentColumnValue("NrDokKonv").ToString();
            autorizime = autorizime.IndexOf(',') == -1 ? autorizime : autorizime.Substring(0, autorizime.Length - 1);
            xrLabel1.Text = autorizime;
}

private void PageHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
   if (this.PrintingSystem.PageCount >= 1)
            {
                e.Cancel = true;
                return;
            }
}

private void ReportHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrPictureBox2.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);
}

private void xrTable4_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 int i = 0;
            if (artikujt.Count > 0)
            {
                xrTable4.Rows.Clear();
                foreach (object[] obj in artikujt)
                {
                    XRTableRow rr = new XRTableRow();
                    rr.HeightF = 25f;
                    XRTableCell kodi = new XRTableCell();
                    kodi.Name = "kodi" + i.ToString();
                    kodi.Text = obj[0].ToString();
                    rr.Cells.Add(kodi);
                    XRTableCell pershkrimi = new XRTableCell();
                    pershkrimi.Name = "pershkrimi" + i.ToString();
                    pershkrimi.Text = obj[1].ToString();
                    rr.Cells.Add(pershkrimi);
                    XRTableCell afatGarancie = new XRTableCell();
                    afatGarancie.Name = "afatGarancie" + i.ToString();
                    afatGarancie.Text = obj[2].ToString();
                    rr.Cells.Add(afatGarancie);
                    XRTableCell llojGarancie = new XRTableCell();
                    llojGarancie.Name = "llojGarancie" + i.ToString();
                    llojGarancie.Text = obj[3].ToString();
                    rr.Cells.Add(llojGarancie);
                    xrTable4.Rows.Insert(i, rr);
                    i++;
                }
            }
}
